package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FieldUtils_safeMultiply_TriageGen1Test {

    @Test
    public void testSafeMultiply_CaseMinusOne_Normal() {
        // Tests case -1 where val1 is not Long.MIN_VALUE
        assertEquals(10L, FieldUtils.safeMultiply(10L, -1));
        assertEquals(-5L, FieldUtils.safeMultiply(5L, -1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, -1));
    }

    @Test(expected = ArithmeticException.class)
    public void testSafeMultiply_CaseMinusOne_Overflow() {
        // Tests case -1 where val1 is Long.MIN_VALUE (overflows when negated)
        FieldUtils.safeMultiply(Long.MIN_VALUE, -1);
    }

    @Test
    public void testSafeMultiply_CaseZero() {
        // Tests case 0
        assertEquals(0L, FieldUtils.safeMultiply(100L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(-100L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 0));
    }

    @Test
    public void testSafeMultiply_CaseOne() {
        // Tests case 1
        assertEquals(100L, FieldUtils.safeMultiply(100L, 1));
        assertEquals(-100L, FieldUtils.safeMultiply(-100L, 1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 1));
    }

    @Test(expected = ArithmeticException.class)
    public void testSafeMultiply_DefaultCase_ThrowsException() {
        // Tests the default case (val2 not in -1, 0, 1)
        // Due to the 'if (true)' block in the provided code, this will always throw
        FieldUtils.safeMultiply(10L, 2);
    }
}
